CREATE TABLE prj24_assets (asset_id INTEGER PRIMARY KEY, asset_name TEXT NOT NULL, quantity INTEGER NOT NULL CHECK (quantity >= 0), asset_state TEXT NOT NULL);
INSERT INTO prj24_assets VALUES (1, 'Laptop', 8, 'active'), (2, 'Projector', 2, 'active');
UPDATE prj24_assets SET quantity = quantity - 1 WHERE asset_id = 2 AND quantity >= 1;
SELECT asset_id, asset_name, quantity FROM prj24_assets ORDER BY asset_id;

